minimal_patch:
在 syncDailyBoard 的席位循环中，将 recoverArtifact(root,record,agent,seat); 替换为：
const recovered = recoverArtifact(root,record,agent,seat);
if (recovered && seat.status === 'generated_pending_sync') {
  seat.sync_reason = 'immutable_artifact_verified_from_prior_crash';
  saveLedger(root, record);
  continue;
}
if (recovered === false && seat.status === 'generation_started') {
  seat.status = 'generation_unknown_no_repurchase';
  seat.sync_reason = 'no_unique_complete_artifact_outcome_unknown';
  saveLedger(root, record);
  continue;
}
